import{_ as o,o as e,c as l,ag as a}from"./chunks/framework.D64lb950.js";const p=JSON.parse('{"title":"《思考，快与慢》读书笔记 - 你的大脑一直在骗你","description":"","frontmatter":{"title":"《思考，快与慢》读书笔记 - 你的大脑一直在骗你","date":"2026-06-24T00:00:00.000Z","tags":["读书笔记","心理学","认知偏差","决策"],"category":"读书笔记"},"headers":[],"relativePath":"posts/thinking-fast-and-slow-review.md","filePath":"posts/thinking-fast-and-slow-review.md","lastUpdated":null}'),r={name:"posts/thinking-fast-and-slow-review.md"};function n(s,t,i,u,q,d){return e(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="《思考-快与慢》读书笔记-你的大脑一直在骗你" tabindex="-1">《思考，快与慢》读书笔记 - 你的大脑一直在骗你 <a class="header-anchor" href="#《思考-快与慢》读书笔记-你的大脑一直在骗你" aria-label="Permalink to &quot;《思考，快与慢》读书笔记 - 你的大脑一直在骗你&quot;">​</a></h1><p>这是一本让我&quot;不舒服&quot;的书。不是难读——卡尼曼的写作非常清晰，实验案例也讲得引人入胜。不舒服是因为<strong>几乎每一章都在告诉你：你以为是自己思考出来的结论，其实是大脑替你走了捷径。</strong></p><p>读完这本书有个后遗症：你会开始怀疑自己的每一个判断。比如写完上一段话，我就想——&quot;我是不是因为刚读完这本书，才觉得它特别有道理？这就是书里说的&#39;可得性偏差&#39;在起作用。&quot;</p><p>丹尼尔·卡尼曼是心理学教授，却拿了诺贝尔经济学奖。因为他的研究直接推翻了经济学的基本假设——<strong>人不是理性的。</strong> 你的每一个判断、每一次选择，都在被你自己意识不到的力量推着走。</p><hr><h2 id="两套系统-你的大脑是双核的" tabindex="-1">两套系统：你的大脑是双核的 <a class="header-anchor" href="#两套系统-你的大脑是双核的" aria-label="Permalink to &quot;两套系统：你的大脑是双核的&quot;">​</a></h2><p>卡尼曼把大脑分成两套系统，这是他整个理论的基石：</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">系统 1（快）</th><th style="text-align:left;">系统 2（慢）</th></tr></thead><tbody><tr><td style="text-align:left;">运作方式</td><td style="text-align:left;">自动、直觉、无意识</td><td style="text-align:left;">受控、理性、有意识</td></tr><tr><td style="text-align:left;">能量消耗</td><td style="text-align:left;">极低，几乎不费力</td><td style="text-align:left;">极高，消耗大量葡萄糖</td></tr><tr><td style="text-align:left;">速度</td><td style="text-align:left;">瞬间反应（毫秒级）</td><td style="text-align:left;">需要集中注意力（秒到分钟）</td></tr><tr><td style="text-align:left;">准确度</td><td style="text-align:left;">容易出错</td><td style="text-align:left;">相对准确</td></tr><tr><td style="text-align:left;">在线时间</td><td style="text-align:left;">24 小时不间断</td><td style="text-align:left;">能偷懒就偷懒</td></tr><tr><td style="text-align:left;">举例</td><td style="text-align:left;">看到 2+2 自动想到 4</td><td style="text-align:left;">算 17×24 需要停下来想</td></tr></tbody></table><p><strong>绝大部分时候，是系统 1 在替你开车。</strong> 你以为自己是理性的，但系统 2 大部分时间在打瞌睡——它只在系统 1 遇到困难时才会被叫醒。</p><p>问题是：系统 1 虽然快，但它偷工减料。它靠的是&quot;启发式&quot;——说白了就是经验法则、直觉、捷径。大部分时候还行，可一旦遇到复杂问题，系统 1 就会系统性地犯错。</p><p><strong>而且系统 2 很懒。</strong> 它有一个监控功能，理论上可以在系统 1 要犯错时出手纠正。但系统 2 倾向于不干涉——因为它每工作一会儿就累得要死。</p><p>🎯 <strong>认识两套系统本身就是一种防御。</strong> 知道自己&quot;第一反应可能是错的&quot;，就给自己留出了让系统 2 介入的空间。</p><hr><h2 id="启动效应-你看不到的隐形手" tabindex="-1">启动效应：你看不到的隐形手 <a class="header-anchor" href="#启动效应-你看不到的隐形手" aria-label="Permalink to &quot;启动效应：你看不到的隐形手&quot;">​</a></h2><p>这是全书让我最不安的一章。</p><p>实验是这样的：让受试者用&quot;老人&quot;&quot;皱纹&quot;&quot;健忘&quot;&quot;灰白&quot;等词造句。做完之后，他们离开实验室走走廊的速度<strong>明显变慢了</strong>——比用&quot;活力&quot;&quot;年轻&quot;&quot;奔跑&quot;等词造句的人慢得多。</p><p>没人意识到刚才的词汇影响了自己。所有人都不觉得那些关键词和走路速度有什么关系。但影响确实发生了。</p><p>这就是<strong>启动效应</strong>：你看到、听到的东西，会激活你大脑中相关的概念网络，然后影响你接下来的行为和判断——<strong>而你完全意识不到。</strong></p><p>更可怕的例子：在一个实验里，人们被要求在软饮和巧克力之间做选择。如果有人在电脑上显示&quot;内疚&quot;&quot;羞愧&quot;等负面词汇（快到看不清），人们选择巧克力的比例大幅降低。但如果显示&quot;快乐&quot;&quot;享受&quot;等正面词汇，巧克力被选中的比例就高了。</p><p><strong>你以为你在自由选择。但自由意志可能比你以为的脆弱得多。</strong></p><hr><h2 id="认知放松-熟悉-安全-正确" tabindex="-1">认知放松：熟悉 = 安全 = 正确 <a class="header-anchor" href="#认知放松-熟悉-安全-正确" aria-label="Permalink to &quot;认知放松：熟悉 = 安全 = 正确&quot;">​</a></h2><p>大脑有一条默认规则：<strong>认知放松的感觉代表&quot;一切正常&quot;，认知紧张的感觉代表&quot;有危险&quot;。</strong></p><p>什么是认知放松？——字大一点、颜色深一点、语言流畅一点、让你联想到熟悉的事物——这些都会让你进入&quot;认知放松&quot;状态。在这个状态下，你更倾向于相信眼前的信息。</p><p>反过来，字太小、排版拥挤、表达拗口——这些让你进入&quot;认知紧张&quot;状态，你会变得更谨慎、更爱挑错。</p><p><strong>这意味着：一个陈述是否&quot;看起来可信&quot;，和信息本身是否正确——是两码事。</strong></p><p>扎心的是，写代码的人应该最懂这个——一段代码写得&quot;好看&quot;（排版整齐、命名优雅），我们就更容易觉得它没问题。但命名优雅和逻辑正确没有任何因果关系。</p><hr><h2 id="可得性偏差-你以为重要的-不一定真的重要" tabindex="-1">可得性偏差：你以为重要的，不一定真的重要 <a class="header-anchor" href="#可得性偏差-你以为重要的-不一定真的重要" aria-label="Permalink to &quot;可得性偏差：你以为重要的，不一定真的重要&quot;">​</a></h2><p>这是我在实际生活中用到最多的一个概念。</p><blockquote><p>&quot;人们会高估自己最近看到、听到、经历过的事件的重要性。&quot;</p></blockquote><p>简单来说：<strong>大脑把&quot;容易想到&quot;当成了&quot;经常发生&quot;。</strong></p><p>飞机失事的新闻铺天盖地报道之后，你会觉得坐飞机很危险。但实际上飞机是全世界最安全的交通工具，死亡率远低于汽车。只是汽车事故太常见了，上不了头条，所以你想不起来。</p><p>同样的道理：</p><ul><li>朋友圈里到处都是升职加薪的消息——你觉得大家都过得很好。因为没人发自己被裁、被PUA、被生活毒打的日常。</li><li>看多了 XX 框架的赞美帖——你觉得它一定是趋势。因为踩坑的人没空写文章歌颂。</li><li>刚开完安全培训会——你觉得安全问题是最紧急的事。不是因为安全真的变差了，是因为安全话题刚被&quot;可得&quot;了一次。</li></ul><p>🎯 <strong>我的一个习惯：每当我觉得一个东西&quot;特别重要&quot;时，先问自己——&quot;是不是因为我最近老看到它？&quot;</strong></p><hr><h2 id="锚定效应-第一个数字会黏在你脑子里" tabindex="-1">锚定效应：第一个数字会黏在你脑子里 <a class="header-anchor" href="#锚定效应-第一个数字会黏在你脑子里" aria-label="Permalink to &quot;锚定效应：第一个数字会黏在你脑子里&quot;">​</a></h2><p>这个实验很经典：让人估计联合国里非洲国家占比。在提问之前，先在受试者面前转一个轮盘，停在一个随机数字上（比如 10 或 65）。</p><p>结果是——<strong>看到 10 的人估计值偏小，看到 65 的人估计值偏大。</strong> 即使他们明知道那个轮盘数字是完全随机的。</p><p>这就是锚定效应：<strong>第一个出现在你脑子里的数字，会像一个船锚一样把你的后续估计钉在它附近，让你无法飘远。</strong></p><p>这在现实里无处不在：</p><ul><li>原价 999，现价 499——&quot;打五折，划算！&quot;但你怎么知道它一开始值不值 999？</li><li>面试谈薪资，HR 先报一个数——你后面再怎么谈，都会被那个初始数字锚住。</li><li>估工期被问了句&quot;两周能搞定吗？&quot;——即使你心里想的是四周，你的答案也会往两周那边偏。</li></ul><p><strong>谈判时永远让对方先出价是一个常见的智慧——但卡尼曼的研究告诉你为什么：因为锚定效应真的存在。</strong></p><hr><h2 id="过度自信-你以为你知道" tabindex="-1">过度自信：你以为你知道 <a class="header-anchor" href="#过度自信-你以为你知道" aria-label="Permalink to &quot;过度自信：你以为你知道&quot;">​</a></h2><blockquote><p>&quot;我们对自己认为知道的，往往过于自信；对自己不知道的，却一无所知。&quot;</p></blockquote><p>卡尼曼在这章里讲了一个让人如坐针毡的实验：让一群人对一系列事实性陈述给出置信区间（比如&quot;我 90% 确定中国人口在 X 到 Y 之间&quot;）。结果发现——<strong>人们给出的 90% 置信区间，正确率只有 50% 左右。</strong></p><p>也就是说，当你觉得自己&quot;十拿九稳&quot;时，实际只对了一半。</p><p>这种过度自信在专家身上更严重。越是领域里的权威，越容易高估自己的判断能力——因为他们见过了足够多支持自己观点的证据，却很少被系统性地质疑。</p><p>🎯 <strong>所以我现在要求自己：凡是我说&quot;肯定&quot;&quot;一定&quot;&quot;毫无疑问&quot;的事，停下来问自己——我能不能列出一条反驳自己的证据？列不出来就是没在认真想。</strong></p><hr><h2 id="前景理论-失去比得到更痛" tabindex="-1">前景理论：失去比得到更痛 <a class="header-anchor" href="#前景理论-失去比得到更痛" aria-label="Permalink to &quot;前景理论：失去比得到更痛&quot;">​</a></h2><p>卡尼曼因此拿了诺贝尔经济学奖。核心发现很简单，但颠覆性极强：</p><p><strong>失去 100 块钱的痛苦，大约是得到 100 块钱的快乐的两倍。</strong></p><p>这就是<strong>损失厌恶</strong>。它解释了很多传统经济学解释不了的现象：</p><table tabindex="0"><thead><tr><th style="text-align:left;">现象</th><th style="text-align:left;">传统经济学的困惑</th><th style="text-align:left;">前景理论的解释</th></tr></thead><tbody><tr><td style="text-align:left;">被套牢的股票为什么不卖？</td><td style="text-align:left;">理性人应该止损</td><td style="text-align:left;">卖了就是确认损失，不卖还能假装没亏</td></tr><tr><td style="text-align:left;">为什么&quot;免费送货&quot;比&quot;便宜 10 元&quot;效果好？</td><td style="text-align:left;">折扣金额一样</td><td style="text-align:left;">&quot;失去 10 元&quot;是痛苦，&quot;额外付运费&quot;是双重损失</td></tr><tr><td style="text-align:left;">为什么宁可维持现状也不冒险改变？</td><td style="text-align:left;">期望值可能是正的</td><td style="text-align:left;">改变的潜在损失比潜在收益更&quot;重&quot;</td></tr></tbody></table><p><strong>作为一个写代码的人，我马上想到的是——这解释了为什么新技术推广这么难。</strong> 换一套技术栈的&quot;潜在损失&quot;（学习成本、踩坑风险、被同事质疑……）在心理上比它&quot;潜在收益&quot;重两倍。理性上你可能知道新工具更好，但情感上你下不了决心——因为损失厌恶在拽着你。</p><hr><h2 id="两个自我-体验自我-vs-记忆自我" tabindex="-1">两个自我：体验自我 vs 记忆自我 <a class="header-anchor" href="#两个自我-体验自我-vs-记忆自我" aria-label="Permalink to &quot;两个自我：体验自我 vs 记忆自我&quot;">​</a></h2><p>这是全书最哲学的一章，也是我思考最久的部分。</p><p>卡尼曼区分了两种&quot;自我&quot;：</p><ul><li><strong>体验自我</strong>：当下正在经历的那个你。每分钟每分钟地过，活在连续的现在。</li><li><strong>记忆自我</strong>：事后回忆和评价的那个你。它只记得片段——而且是扭曲过的片段。</li></ul><p>问题是：<strong>是记忆自我在替你做决定，而记忆自我根本不在乎你体验了什么。</strong></p><p>他做了一个著名的&quot;冰水实验&quot;：</p><p>让受试者把手放进 14°C 的冷水里 60 秒（很痛）。然后另一只手放进 14°C 冷水里 60 秒 + 继续放 30 秒但水温悄悄升到 15°C（还是很冷但稍微好一点）。</p><p>结果——<strong>80% 的人选择再重复第二种情况</strong>，尽管它在客观上多受了 30 秒的罪。因为记忆自我不记录&quot;总的痛苦量&quot;，它只记录&quot;最痛的一刻&quot;和&quot;最后一刻&quot;。&quot;结尾稍微好一点&quot;让整段记忆变得更好接受。</p><p><strong>这个发现太扎心了：你做的决定，不是为了让未来的自己&quot;更幸福&quot;，而是为了给记忆自我创造&quot;更好的故事&quot;。</strong></p><hr><h2 id="认知偏差在编程和技术决策中的表现" tabindex="-1">认知偏差在编程和技术决策中的表现 <a class="header-anchor" href="#认知偏差在编程和技术决策中的表现" aria-label="Permalink to &quot;认知偏差在编程和技术决策中的表现&quot;">​</a></h2><p>读这本书的时候，我一直在做一件事：把我的日常技术工作往书里的偏差框架里套。结果是——几乎每个偏差都能在编程场景里找到对应：</p><table tabindex="0"><thead><tr><th style="text-align:left;">偏差</th><th style="text-align:left;">编程场景</th></tr></thead><tbody><tr><td style="text-align:left;">可得性偏差</td><td style="text-align:left;">最近看到一个框架被吹爆了，就觉得它是技术趋势</td></tr><tr><td style="text-align:left;">锚定效应</td><td style="text-align:left;">听了第一个方案后就很难考虑不同的架构</td></tr><tr><td style="text-align:left;">过度自信</td><td style="text-align:left;">程序员是&quot;这个 bug 几分钟就能修好&quot;的重度患者</td></tr><tr><td style="text-align:left;">损失厌恶</td><td style="text-align:left;">在一个老旧技术栈上修修补补，就是不肯花时间迁移</td></tr><tr><td style="text-align:left;">确认偏误</td><td style="text-align:left;">代码 Review 时只看到支持自己观点的证据</td></tr><tr><td style="text-align:left;">后见之明</td><td style="text-align:left;">&quot;这个 bug 这么明显我当初怎么没想到？&quot;——当时你就是想不到</td></tr><tr><td style="text-align:left;">框架效应</td><td style="text-align:left;">&quot;成功率 90%&quot;和&quot;失败率 10%&quot;是同一件事，但前者听着更安心</td></tr></tbody></table><p>最值得警惕的是<strong>确认偏误</strong>——程序员写代码的时候，只测试&quot;能跑通&quot;的情况，很少去刻意构造&quot;应该报错&quot;的测试用例。这不是懒，是<strong>大脑天生就不想看到自己错了。</strong></p><hr><h2 id="用芒格的思维模型武装系统-2" tabindex="-1">用芒格的思维模型武装系统 2 <a class="header-anchor" href="#用芒格的思维模型武装系统-2" aria-label="Permalink to &quot;用芒格的思维模型武装系统 2&quot;">​</a></h2><p>读这本书之前我先读了《穷查理宝典》，重读时发现两本书之间有非常深的呼应。</p><p>芒格说的&quot;思维模型&quot;，本质上就是<strong>给系统 2 配一套武器</strong>。系统 1 会自动跳出来给你第一反应，这个你控制不了。但你可以通过刻意训练，让系统 2 在关键节点介入：</p><ul><li>当你感觉&quot;这事肯定没问题&quot;——提醒自己这是<strong>过度自信</strong></li><li>当你因为最近老看到某新闻而焦虑——提醒自己这是<strong>可得性偏差</strong></li><li>当你因为别人先说了个价格而觉得合理——提醒自己这是<strong>锚定效应</strong></li><li>当你不愿意止损一笔投资或一个错误决策——提醒自己这是<strong>损失厌恶</strong></li></ul><p><strong>卡尼曼告诉你问题在哪里，芒格告诉你怎么建立防御系统。</strong> 两本书一起读，效果翻倍。</p><hr><h2 id="我的认知错漏清单与改善计划" tabindex="-1">我的认知错漏清单与改善计划 <a class="header-anchor" href="#我的认知错漏清单与改善计划" aria-label="Permalink to &quot;我的认知错漏清单与改善计划&quot;">​</a></h2><p>读完这本书之后，我做了一个&quot;认知错漏检查清单&quot;，做重要决策前会快速过一遍：</p><p><strong>决策前自检</strong></p><ul><li>[ ] 我是不是因为最近频繁看到某信息，才觉得它重要？（可得性）</li><li>[ ] 有没有一个&quot;锚&quot;在影响我的估计？（锚定）</li><li>[ ] 我给出的置信度是不是太高了？列一条反驳证据（过度自信）</li><li>[ ] 我是不是因为&quot;不想承认之前错了&quot;才坚持？（一致性倾向）</li><li>[ ] 这个选择框架换一种说法，我会做不同决定吗？（框架效应）</li></ul><p><strong>日常认知习惯</strong></p><ul><li>听到任何新闻先停顿 5 秒再下判断——给系统 2 一个上场的机会</li><li>重要决策隔 24 小时再确认一次——利用睡眠让系统 2 有充分时间参与</li><li>找人给自己当&quot;魔鬼代言人&quot;——主动寻求与自己相反的立场</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><p>这个系列的其他几篇：</p><ul><li><a href="/my-blog/posts/poor-charlies-almanack-review">《穷查理宝典》读书笔记</a> —— 芒格的多元思维模型，给系统 2 配一套武器</li><li><a href="/my-blog/posts/seven-habits-review">《高效能人士的七个习惯》读书笔记</a> —— 如何把认知洞察转化为日常习惯</li><li><a href="/my-blog/posts/nonviolent-communication-review">《非暴力沟通》读书笔记</a> —— 认知偏差如何影响你的沟通方式</li><li><a href="/my-blog/posts/deliberate-practice-review">《刻意练习》读书笔记</a> —— 如何通过刻意练习建立更好的心理表征</li><li><a href="/my-blog/posts/good-books-recommendation">值得反复阅读的几本好书</a> —— 5 本书的简要速览</li></ul><hr><p><strong>最后记住卡尼曼的这句话：</strong></p><blockquote><p>&quot;我们对自己认为知道的，往往过于自信；对自己不知道的，却一无所知。&quot;</p></blockquote>',93)])])}const h=o(r,[["render",n]]);export{p as __pageData,h as default};
